with cleaned as (select *, round(budget, 0) budget_rounded, case when dept_name in ('Sales', 'Legal') then 'Tier 1' else 'Other' end dept_name_group, coalesce(location, 'NONE') location_clean from departments where budget >= 2907000) select id, dept_name, budget, dept_name_group, last_value(location) ignore nulls over (partition by location order by budget_rounded, id rows between unbounded preceding and current row) last_known_location, lead(budget_rounded, 2) over (order by budget_rounded, id) next_budget_rounded from cleaned
